import os
import torch


class Config:
    # ==============================
    # General Configuration
    # ==============================
    seed = 42
    device = "cuda" if torch.cuda.is_available() else "cpu"
    num_workers = 2  # For data loading

    # ==============================
    # Data Paths
    # ==============================
    # Metadata paths (generated by the metadata script)
    train_metadata = "./metadata/train.parquet"
    val_metadata = "./metadata/val.parquet"
    test_metadata = "./metadata/test.parquet"

    # Raw input paths
    sample_submission_path = "./input/sample_submission.csv"

    # Output directories
    working_dir = "./working/idea_42"
    submission_dir = "./submission"
    submission_path = os.path.join(submission_dir, "submission.csv")
    model_save_path = os.path.join(working_dir, "best_model.pth")

    # Ensure working directories exist
    os.makedirs(working_dir, exist_ok=True)
    os.makedirs(submission_dir, exist_ok=True)

    # ==============================
    # Data Specifics
    # ==============================
    seq_len = 107
    pred_len = 68

    # Target columns to train on (filtering out deg_pH10 and deg_50C)
    target_cols = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    num_targets = len(target_cols)

    # Vocabularies
    # Atomic Sequence: A, G, C, U
    token2id = {"A": 0, "G": 1, "C": 2, "U": 3}
    vocab_size = len(token2id)

    # Predicted Loop Type: S, M, I, B, H, E, X
    loop2id = {"S": 0, "M": 1, "I": 2, "B": 3, "H": 4, "E": 5, "X": 6}
    loop_vocab_size = len(loop2id)

    # ==============================
    # Model Architecture
    # ==============================
    # Proportional Feature Embeddings
    embedding_dim = 128  # Atomic Sequence
    loop_dim = 64  # Predicted Loop Type
    pair_dim = 64  # Signed Sinusoidal Pairing Distance

    # Total input dimension = 128 + 64 + 64 = 256
    input_dim = embedding_dim + loop_dim + pair_dim

    # Recurrent Backbone
    hidden_dim = 384  # Residual stream width (W=384)
    num_layers = 6  # Number of Wide-Stream Residual Blocks
    dropout = 0.2  # Inter-layer dropout

    # Structure-Biased Attention
    nhead = 4  # Number of attention heads

    # ==============================
    # Training Hyperparameters
    # ==============================
    epochs = 20
    batch_size = 32
    lr = 1e-3
    weight_decay = 1e-4

    # Gradient Clipping (Critical for stability)
    clip_grad = 1.0

    # Scheduler
    T_max = epochs  # For Cosine Annealing
    min_lr = 1e-6

    def __init__(self):
        # Optional: Instance-level initialization if needed
        pass

    @classmethod
    def display(cls):
        """Prints the configuration."""
        print("=" * 30)
        print("CONFIG")
        print("=" * 30)
        for k, v in cls.__dict__.items():
            if not k.startswith("__") and not callable(v):
                print(f"{k}: {v}")
        print("=" * 30)
